/**
 * How each Astrochimp NFT design looks as a 3D character in Astroworld.
 *
 * characters.json (generated by scripts/make-world-characters.mjs) lists every
 * design with its art and auto-picked colours. The table below is hand-tuned
 * from looking at each NFT's art: outfit silhouette, headwear and the colours
 * people recognise. A design missing from the table (a newly added style)
 * still works - it falls back to casual wear in its auto colours.
 *
 * When real rigged models exist, they replace this per character (see
 * docs/3d-characters.md) - the ids here stay the same.
 */
import characters from "./characters.json";

export type Outfit = "suit" | "armor" | "coat" | "gown" | "casual" | "royal";
export type Headwear = "helmet" | "hood" | "fedora" | "crown" | "cap" | "hair" | "goggles" | "tactical" | "bandana" | "none";
export type Species = "chimp" | "dog" | "cat";
/** The signature item a character carries in the safe zone (everyone draws a rifle outside it). */
export type Gear = "rifle" | "blade" | "pickaxe" | "none";

export interface CharacterLook {
  id: string;
  name: string;
  tier: "common" | "rare" | "one_of_one";
  /** NFT art thumbnail, site-relative. */
  image: string;
  outfit: Outfit;
  head: Headwear;
  species: Species;
  gear: Gear;
  /** Main outfit colour. */
  suit: string;
  /** Secondary colour: stripes, hood, cape, trims. */
  trim: string;
  /** Emissive accent: visor, light strips, weapon glow. */
  glow: string;
  fur: string;
  /** Hair colour, when head === "hair". */
  hair?: string;
}

type Look = Pick<CharacterLook, "outfit" | "head" | "suit" | "trim" | "glow"> & Partial<Pick<CharacterLook, "species" | "gear" | "fur" | "hair">>;

const L = (outfit: Outfit, head: Headwear, suit: string, trim: string, glow: string, extra: Partial<Look> = {}): Look => ({
  outfit,
  head,
  suit,
  trim,
  glow,
  ...extra,
});

