interface GeneratedCharacter {
  id: string;
  name: string;
  tier: string;
  image: string;
  suit: string;
  trim: string;
  glow: string;
  fur: string;
}

export const CHARACTERS: CharacterLook[] = (characters as GeneratedCharacter[]).map((c) => {
  const look = LOOKS[c.id];
  return {
    id: c.id,
    name: c.name,
    tier: c.tier as CharacterLook["tier"],
    image: c.image,
    outfit: look?.outfit ?? "casual",
    head: look?.head ?? "none",
    species: look?.species ?? "chimp",
    gear: look?.gear ?? "none",
    suit: look?.suit ?? c.suit,
    trim: look?.trim ?? c.trim,
    glow: look?.glow ?? c.glow,
    fur: look?.fur ?? "#4a2f1d",
    hair: look?.hair,
  };
});

const BY_ID = new Map(CHARACTERS.map((c) => [c.id, c]));

/** Worn until a player picks - a Common, like most players start with. */
export const DEFAULT_CHARACTER_ID = "std-billy-the-chimp";

export const TIER_LABEL: Record<CharacterLook["tier"], string> = {
  common: "Common",
  rare: "Rare",
  one_of_one: "One of One",
};

/** Tier colours for name tags and cards. */
export const TIER_COLOR: Record<CharacterLook["tier"], string> = {
  common: "#cbd5e1",
  rare: "#c084fc",
  one_of_one: "#fbbf24",
};

export function isCharacterId(id: unknown): id is string {
  return typeof id === "string" && BY_ID.has(id);
}

export function characterById(id: string | undefined): CharacterLook {
  return (id && BY_ID.get(id)) || BY_ID.get(DEFAULT_CHARACTER_ID) || CHARACTERS[0];
}

/**
 * On-chain names are "<style name> #<mint number>" (see app/api/mint/claim),
 * so an owned NFT maps back to its design by the longest matching name prefix.
 */
export function characterForNftName(nftName: string): CharacterLook | null {
  const base = nftName.replace(/\s*#\d+\s*$/, "").trim().toLowerCase();
  return CHARACTERS.find((c) => c.name.toLowerCase() === base) ?? null;
}
